// CapabilityBinding Selects which verified provider fulfils a capability class for a given Intent kind (ADR-0110 D3), so an Intent's `requires: [provisioning]` resolves to a concrete provider + build Workflow. A CaC declaration FORM the capability registry reconciles — NOT a Named Kind (§2 frozen); the binding selects only the provider (the provider owns its per-kind build Workflow via its `provisions` map).
type CapabilityBinding struct {
	Entries      []CapabilityBindingEntry `json:"entries"`
	Environments *[]string                `json:"environments,omitempty"`
	Name         string                   `json:"name"`
}

// CapabilityBindingEntry One capability→provider selection for a specific Intent kind (ADR-0110 D3).
type CapabilityBindingEntry struct {
	// Capability The capability class being bound (e.g. provisioning) — a core-owned class (§1.5).
	Capability string `json:"capability"`

	// IntentKind The Intent kind this entry routes, WITHOUT the "Intent/" prefix (e.g. Compute, Subnet, Vlan, Dmz).
	IntentKind string `json:"intentKind"`

	// Provider The verified provider's declaration name (an Actuator/Connector that `provides` the class).
	Provider string `json:"provider"`
}

// CapabilityVerification A capability PROVIDER's verification outcome (ADR-0104 D1): whether the provider's dialed Manifest actually backs the capability classes it declares it `provides`. Absent for a declaration that provides nothing. The descent surface (§1.8) for a phantom provider — a declared `provides` its plugin does not advertise is verified=false and never counts.
type CapabilityVerification struct {
	// Basis HOW the verdict was reached (ADR-0138 D5). `manifest` means the plugin's RUNNING binary was dialed and its own advertisement checked against the operator's `provides` — two independent artifacts agreeing. `declaration` means the provider is dial-less (an EE-Job Actuator has no address by construction, §3 GPLv3 boundary), so there is no Manifest to fetch and the claim was corroborated against the DECLARED mechanisms instead: the per-kind Workflow maps and dispatchable Actions, which the estate loader already validates. Empty when not verified. The two are NOT equally strong, and a surface that renders both as a plain "verified" hides which is which (§1.8).
	Basis *CapabilityVerificationBasis `json:"basis,omitempty"`

	// Implements The capability class → Action name mappings this provider's Manifest ADVERTISES, for the classes it was granted (ADR-0140 D1). This is what capability resolution reads; core no longer derives the name. Absent/empty is normal — only classes reached through a resolve Action appear here, never one routed through a per-kind Workflow map. It is the descent surface (§1.8) for "why did this capability route to that Action?", which was previously answerable only from a naming convention held in core's head.
	Implements *map[string]string `json:"implements,omitempty"`

	// Reason The phantom/pending reason when verified=false; empty when verified.
	Reason   *string `json:"reason,omitempty"`
	Verified bool    `json:"verified"`
}

// CapabilityVerificationBasis HOW the verdict was reached (ADR-0138 D5). `manifest` means the plugin's RUNNING binary was dialed and its own advertisement checked against the operator's `provides` — two independent artifacts agreeing. `declaration` means the provider is dial-less (an EE-Job Actuator has no address by construction, §3 GPLv3 boundary), so there is no Manifest to fetch and the claim was corroborated against the DECLARED mechanisms instead: the per-kind Workflow maps and dispatchable Actions, which the estate loader already validates. Empty when not verified. The two are NOT equally strong, and a surface that renders both as a plain "verified" hides which is which (§1.8).
type CapabilityVerificationBasis string

